from collections import Counter
from math import gcd
from functools import reduce


def _encode(crossings, background, separator_color):
    out = []
    for r in range(len(crossings) - 1):
        row = []
        for c in range(len(crossings[0]) - 1):
            corners = (crossings[r][c], crossings[r][c + 1], crossings[r + 1][c], crossings[r + 1][c + 1])
            v = corners[0]
            row.append(v if v != separator_color and all(x == v for x in corners) else background)
        out.append(row)
    while out and all(v == background for v in out[0]): out.pop(0)
    while out and all(v == background for v in out[-1]): out.pop()
    while out and out[0] and all(row[0] == background for row in out):
        for row in out: row.pop(0)
    while out and out[0] and all(row[-1] == background for row in out):
        for row in out: row.pop()
    return out


def _period_for_marks(positions):
    diffs = [b-a for a,b in zip(positions, positions[1:])]
    return reduce(gcd, diffs)


def transform(grid):
    h,w=len(grid),len(grid[0])
    counts=Counter(v for row in grid for v in row)
    abundant={v for v,_ in counts.most_common(2)}
    rare={v for v in counts if v not in abundant}
    mr=[r for r,row in enumerate(grid) if any(v in rare for v in row)]
    mc=[c for c in range(w) if any(grid[r][c] in rare for r in range(h))]
    rp=_period_for_marks(mr); cp=_period_for_marks(mc)
    rr=Counter(r%rp for r in mr).most_common(1)[0][0]
    cr=Counter(c%cp for c in mc).most_common(1)[0][0]
    rlines=[r for r in range(h) if r%rp==rr]
    clines=[c for c in range(w) if c%cp==cr]
    crossings=[[grid[r][c] for c in clines] for r in rlines]
    tile=[grid[r][c] for r in range(h) if r not in rlines for c in range(w) if c not in clines]
    background=Counter(tile).most_common(1)[0][0]
    separator=next(v for v,_ in counts.most_common(2) if v!=background)
    return _encode(crossings,background,separator)", "exit_code": 0, "error": null}

